  "anomalies": [
    {
      "category": "wrong_value",
      "components": ["R36"],
      "pins": ["R36.1", "R36.2"],
      "nets": ["VOUTN", "VOUTP"],
      "observed": "R36 is assigned a value of 24k, but its MPN, FRC0805J240TSD, and its description specify 24Ω.",
      "expected": "The sourced part should match the intended 24k value, or the schematic value should be corrected if 24Ω is intended.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(comp (ref \"R36\") (value \"24k\")"
        },
        {
          "source": "netlist",
          "quote": "(field (name \"MPN\") \"FRC0805J240TSD\")"
        },
        {
          "source": "netlist",
          "quote": "125mW Thick Film Resistors ... ±5% 24Ω 0805 Chip Resistor"
        },
        {
          "source": "netlist",
          "quote": "(node (ref \"R36\") (pin \"1\") ... (net (name \"VOUTN\"))"
        },
        {
          "source": "netlist",
          "quote": "(node (ref \"R36\") (pin \"2\") ... (net (name \"VOUTP\"))"
        }
      ],
      "impact": "If the listed MPN is used for sourcing, a 24Ω resistor will be installed across VOUTP and VOUTN instead of the 24kΩ load shown in the schematic. That much lower resistance could heavily load the output and prevent the associated circuit from operating as intended.",
      "confidence": 0.82
    }
  ],
  "summary": "R36 has a significant value-to-sourcing mismatch: the schematic says 24kΩ, while its MPN and component description specify 24Ω. If the MPN is followed, the output will be loaded far more heavily than the schematic indicates."
}

